alter table "user" add column if not exists "last_organization_id" text;

alter table "session" add column if not exists "active_organization_id" text;

create table if not exists "organization" ("id" text not null primary key, "name" text not null, "slug" text not null unique, "logo" text, "created_at" timestamptz not null, "metadata" text);

create table if not exists "member" ("id" text not null primary key, "organization_id" text not null references "organization" ("id") on delete cascade, "user_id" text not null references "user" ("id") on delete cascade, "role" text not null, "created_at" timestamptz not null, "app_roles" jsonb);

create table if not exists "invitation" ("id" text not null primary key, "organization_id" text not null references "organization" ("id") on delete cascade, "email" text not null, "role" text, "status" text not null, "expires_at" timestamptz not null, "created_at" timestamptz default CURRENT_TIMESTAMP not null, "inviter_id" text not null references "user" ("id") on delete cascade, "app_roles" jsonb);

create index if not exists "member_organization_id_idx" on "member" ("organization_id");

create index if not exists "member_user_id_idx" on "member" ("user_id");

create index if not exists "invitation_organization_id_idx" on "invitation" ("organization_id");

create index if not exists "invitation_email_idx" on "invitation" ("email");
